def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({x for row in grid for x in row},
             key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]
    cells = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                cells.setdefault(grid[r][c], []).append((r, c))

    for color, pts in cells.items():
        # A diagonal pair defines the line to extend.
        pair = None
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                if abs(r2-r1) == abs(c2-c1):
                    pair = (r1, c1, r2-r1, c2-c1)
                    break
            if pair:
                break
        if not pair:
            continue

        r, c, vr, vc = pair
        dr = 1 if vr > 0 else -1
        dc = 1 if vc > 0 else -1

        # Walk the line in both directions, stopping at other colored cells
        # or the edge of the grid.
        for sr, sc in ((dr, dc), (-dr, -dc)):
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] != bg and grid[rr][cc] != color:
                    break
                if grid[rr][cc] == bg:
                    out[rr][cc] = color
                rr += sr
                cc += sc
    return out
